import unittest
from gossipmesh.p2p.ttl import AdaptiveTTLEngine

class TestAdaptiveTTLEngine(unittest.TestCase):
    def setUp(self):
        self.engine = AdaptiveTTLEngine(base_ttl=10, max_queue_depth=100, max_latency_ms=500.0)

    def test_normal_operation_low_congestion(self):
        # Low queue depth and latency should result in minimal decay (e.g., decay by 1)
        new_ttl = self.engine.calculate_decay(current_ttl=10, queue_depth=5, latency_ms=10.0)
        self.assertEqual(new_ttl, 9)

    def test_high_congestion_decay(self):
        # High queue depth and latency should result in aggressive decay
        new_ttl = self.engine.calculate_decay(current_ttl=10, queue_depth=90, latency_ms=450.0)
        self.assertLess(new_ttl, 7)

    def test_poison_reverse_heuristic(self):
        # Poison-reverse flag should immediately drop TTL to 0
        new_ttl = self.engine.calculate_decay(current_ttl=10, queue_depth=10, latency_ms=20.0, is_poison_reverse=True)
        self.assertEqual(new_ttl, 0)

    def test_boundary_zero_ttl(self):
        # Zero or negative current TTL should remain 0
        new_ttl = self.engine.calculate_decay(current_ttl=0, queue_depth=0, latency_ms=0.0)
        self.assertEqual(new_ttl, 0)

if __name__ == '__main__':
    unittest.main()
